<body>
<h1>CHIP-8 Emulator - GPT-4.1 Mini</h1>
<canvas id="chip8-screen" width="64" height="32" style="width:512px; height:256px;"></canvas>
<div id="controls">
  <button id="run-btn">Run</button>
  <button id="pause-btn" disabled>Pause</button>
  <button id="step-btn">Single Step</button>
  <button id="reset-btn">Reset</button>
  <label for="speed-range">Instructions/frame:</label>
  <input type="range" id="speed-range" min="1" max="20" value="10" />
  <span id="speed-value">10</span>
  <input type="file" id="rom-loader" accept=".ch8,.rom,.bin" />
</div>
<div id="keypad"></div>
<div id="debugger">
  <div><strong>Program Counter (PC):</strong> <span id="pc">0x000</span></div>
  <div><strong>Index Register (I):</strong> <span id="index">0x0000</span></div>
  <div><strong>Delay Timer:</strong> <span id="delay-timer">0</span></div>
  <div><strong>Sound Timer:</strong> <span id="sound-timer">0</span></div>
